stages.response:
{
  "entities": [
    {
      "name": "Account",
      "type": "node",
      "attributes": ["account_id"]
    },
    {
      "name": "Party",
      "type": "node",
      "attributes": ["party_id"]
    },
    {
      "name": "Transfer",
      "type": "node",
      "attributes": ["transfer_id"]
    }
  ],
  "relationships": [
    {
      "name": "OWNED_BY",
      "from": "Account",
      "to": "Party",
      "direction": "outgoing"
    },
    {
      "name": "FROM",
      "from": "Transfer",
      "to": "Account",
      "direction": "outgoing"
    },
    {
      "name": "TO",
      "from": "Transfer",
      "to": "Account",
      "direction": "outgoing"
    }
  ],
  "predicates": [
    {
      "description": "Source and destination accounts are distinct",
      "expression": "src.account_id <> dst.account_id"
    },
    {
      "description": "Both accounts share the same owning party",
      "expression": "src-[:OWNED_BY]->p AND dst-[:OWNED_BY]->p"
    },
    {
      "description": "There exists at least one direct transfer from source to destination",
      "expression": "EXISTS ( (t:Transfer)-[:FROM]->src AND (t)-[:TO]->dst )"
    }
  ],
  "aggregation": {
    "type": "count_distinct",
    "target": ["src.account_id", "dst.account_id"],
    "alias": "ordered_pair_count"
  },
  "ordering": null,
  "expected_shape": {
    "type": "single_row",
    "columns": [
      {
        "name": "ordered_pair_count",
        "type": "integer"
      }
    ]
  },
  "assumptions": [
    "Each Account node has exactly one outgoing OWNED_BY edge to a Party node.",
    "Transfer nodes have exactly one outgoing FROM edge to the source Account and one outgoing TO edge to the destination Account.",
    "Self‑transfers (source = destination) are possible in the data but must be excluded by the query."
  ],
  "uncertainties": [
    "Whether ownership is modeled via a property on Account instead of an OWNED_BY edge.",
    "If multiple Transfer nodes can represent the same logical transfer (duplicate records)."
  ],
  "acceptance_tests": [
    {
      "description": "Simple graph with two parties, each owning two accounts, and one transfer from A1→A2 and another from B1→B2.",
      "graph": {
        "accounts": ["A1","A2","B1","B2"],
        "parties": ["P1","P2"],
        "ownership": [
          ["A1","P1"],["A2","P1"],["B1","P2"],["B2","P2"]
        ],
        "transfers": [
          ["T1","A1","A2"],
          ["T2","B1","B2"]
        ]
      },
      "expected_result": 2
    },
    {
      "description": "Graph where three accounts belong to the same party and there are transfers A→B, A→C, B→C, plus a duplicate transfer A→B.",
      "graph": {
        "accounts": ["A","B","C"],
        "party": "P",
        "ownership": [
          ["A","P"],["B","P"],["C","P"]
        ],
        "transfers": [
          ["T1","A","B"],
          ["T2","A","B"],  "duplicate",
          ["T3","A","C"],
          ["T4","B","C"]
        ]
      },
      "expected_result": 3
    }
  ]
}

